{"path": "/app/bin/hourly.py", "content": "#!/usr/bin/env python3
"""Hourly station product: python3 hourly.py INPUT_DIR OUTPUT_FILE (see /app/docs)."""
import json
import math
import os
import re
import sys
from datetime import datetime, timedelta

QUANTITIES = ("temp", "rh", "pres", "wspd", "wdir", "rain")
RANGES = {"temp": (-50, 60), "rh": (0, 100), "pres": (870, 1085),
          "wspd": (0, 60), "wdir": (0, 360), "rain": (0, 5000)}
CONV = {
    ("temp", "degC"): lambda v: v,
    ("temp", "degF"): lambda v: (v - 32) * 5 / 9,
    ("temp", "K"): lambda v: v - 273.15,
    ("rh", "pct"): lambda v: v,
    ("rh", "frac"): lambda v: v * 100,
    ("pres", "hPa"): lambda v: v,
    ("pres", "kPa"): lambda v: v * 10,
    ("pres", "inHg"): lambda v: v * 33.8638866667,
    ("pres", "mmHg"): lambda v: v * 1.33322387415,
    ("wspd", "ms"): lambda v: v,
    ("wspd", "kmh"): lambda v: v / 3.6,
    ("wspd", "kn"): lambda v: v * 1852 / 3600,
    ("wspd", "mph"): lambda v: v * 0.44704,
    ("wdir", "deg"): lambda v: v,
    ("rain", "mm"): lambda v: v,
}
CANON = {"temp": "degC", "rh": "pct", "pres": "hPa", "wspd": "ms",
         "wdir": "deg", "rain": "mm"}

EPOCH = datetime(1970, 1, 1)
DIRECTIVE = re.compile(r"^#\s*([a-z]+)\s*:(.*)$")
TIME_RE = r"\d{4}-\d\d-\d\d[ T]\d\d:\d\d:\d\d"
SYNC_LOGGER = re.compile(r"logger=\s*(" + TIME_RE + ")")
SYNC_REF = re.compile(r"ref=\s*(\d{4}-\d\d-\d\dT\d\d:\d\d:\d\dZ)")
MISSING_RE = re.compile(r"^-9999(\.0*)?$")


def secs(text):
    """Seconds since epoch of a naive 'YYYY-MM-DD[ T]HH:MM:SS' text."""
    text = text.strip().replace("T", " ")
    d = datetime.strptime(text, "%Y-%m-%d %H:%M:%S")
    delta = d - EPOCH
    return delta.days * 86400 + delta.seconds


def parse_tz(text):
    text = text.strip()
    if text in ("Z", "z"):
        return 0
    sign = -1 if text[0] == "-" else 1
    body = text[1:] if text[0] in "+-" else text
    h, m = body.split(":")
    return sign * (int(h) * 3600 + int(m) * 60)


def parse_value(field, quantity, unit):
    f = field.strip()
    if f == "" or f == "---" or f.lower() == "nan" or MISSING_RE.match(f):
        return None
    try:
        v = float(f)
    except ValueError:
        return None
    if math.isnan(v) or math.isinf(v):
        return None
    if unit.startswith("tips:") and quantity == "rain":
        try:
            v = v * float(unit[5:])
        except ValueError:
            return None
    else:
        fn = CONV.get((quantity, unit))
        if fn is None:
            fn = CONV[(quantity, CANON[quantity])]
        v = fn(v)
    lo, hi = RANGES[quantity]
    if v < lo or v > hi:
        return None
    return v


def read_dump(path):
    with open(path, "rb") as fh:
        raw = fh.read()
    text = raw.decode("utf-8", errors="replace")
    if text.startswith("\ufeff"):
        text = text[1:]
    station = None
    upload = 0
    interval = None
    tz = 0
    columns = None
    units = {}
    rows = []   # (utc_instant, {quantity: value})
    syncs = []  # (utc_instant, ref_seconds)
    for line in re.split(r"\r?\n", text):
        if line.strip() == "":
            continue
        if line.lstrip()[0] == "#":
            m = DIRECTIVE.match(line.lstrip())
            if not m:
                continue
            key, value = m.group(1), m.group(2).strip()
            if key == "station":
                station = value
            elif key == "upload":
                upload = int(value)
            elif key == "interval":
                interval = int(float(value))
            elif key == "tz":
                tz = parse_tz(value)
            elif key == "columns":
                columns = [c.strip() for c in value.split(",")]
            elif key == "units":
                for pair in value.split():
                    if "=" in pair:
                        q, u = pair.split("=", 1)
                        units[q] = u
            elif key == "sync":
                lm = SYNC_LOGGER.search(value)
                rm = SYNC_REF.search(value)
                if lm and rm:
                    syncs.append((secs(lm.group(1)) - tz, secs(rm.group(1).rstrip("Z"))))
            continue
        if columns is None:
            continue
        fields = line.split(",")
        rec = dict(zip(columns, fields))
        if "time" not in rec:
            continue
        t = secs(rec["time"]) - tz
        vals = {}
        for q in QUANTITIES:
            if q in rec:
                vals[q] = parse_value(rec[q], q, units.get(q, CANON[q]))
        rows.append((t, vals))
    return station, upload, interval, rows, syncs


def offset_func(syncs):
    pts = sorted(syncs.items())
    pts = [(t, ref - t) for t, ref in [(t, r) for t, r in pts]]
    if not pts:
        return lambda t: 0
    times = [p[0] for p in pts]
    import bisect

    def off(t):
        if t <= times[0]:
            return pts[0][1]
        if t >= times[-1]:
            return pts[-1][1]
        i = bisect.bisect_left(times, t)
        if times[i] == t:
            return pts[i][1]
        t1, o1 = pts[i - 1]
        t2, o2 = pts[i]
        return (o1 * (t2 - t1) + (o2 - o1) * (t - t1)) // (t2 - t1)
    return off


def fmt_hour(h):
    return (EPOCH + timedelta(seconds=h)).strftime("%Y-%m-%dT%H:%M:%SZ")


def r2(x):
    x = round(x, 2)
    return 0.0 if x == 0 else x


def main(indir, outfile):
    stations = {}
    names = sorted(n for n in os.listdir(indir)
                   if n.endswith(".log") and os.path.isfile(os.path.join(indir, n)))
    for name in names:
        station, upload, interval, rows, syncs = read_dump(os.path.join(indir, name))
        if station is None:
            continue
        st = stations.setdefault(station, {"interval": interval, "up": -1,
                                           "rows": {}, "syncs": {}})
        if interval is not None and upload >= st["up"]:
            st["interval"] = interval
            st["up"] = upload
        for t, vals in rows:
            cur = st["rows"].get(t)
            if cur is None or upload > cur[0]:
                st["rows"][t] = (upload, vals)
        for t, ref in syncs:
            cur = st["syncs"].get(t)
            if cur is None or upload > cur[0]:
                st["syncs"][t] = (upload, ref)

    out = {"stations": []}
    for sid in sorted(stations):
        st = stations[sid]
        if not st["rows"]:
            continue
        interval = st["interval"] or 60
        off = offset_func({t: v[1] for t, v in st["syncs"].items()})
        recs = []
        for t, (_, vals) in st["rows"].items():
            recs.append((t + off(t), t, vals))
        recs.sort(key=lambda r: (r[0], r[1]))

        def hour_of(c):
            return -((-c) // 3600) * 3600

        per = {}  # hour -> {q: [values]}, plus wdir vectors, rain incs
        wvec = {}
        rain_inc = {}
        prev_rain = None
        for c, t, vals in recs:
            h = hour_of(c)
            d = per.setdefault(h, {q: [] for q in QUANTITIES})
            for q in QUANTITIES:
                v = vals.get(q)
                if v is not None:
                    d[q].append(v)
            wd, ws = vals.get("wdir"), vals.get("wspd")
            if wd is not None and ws is not None and ws > 0:
                a = math.radians(wd)
                s = wvec.setdefault(h, [0.0, 0.0])
                s[0] += math.sin(a)
                s[1] += math.cos(a)
            rn = vals.get("rain")
            if rn is not None:
                if prev_rain is not None and 2 * (c - prev_rain[0]) <= 5 * interval:
                    p = prev_rain[1]
                    inc = rn - p if rn >= p else rn
                    rain_inc[h] = rain_inc.get(h, 0.0) + inc
                prev_rain = (c, rn)
        lo, hi = hour_of(recs[0][0]), hour_of(recs[-1][0])
        hours = []
        h = lo
        while h <= hi:
            d = per.get(h)
            entry = {"hour": fmt_hour(h)}
            for q in QUANTITIES:
                n = len(d[q]) if d else 0
                ok = n > 0 and n * 4 * interval >= 3600 * 3
                value = None
                if ok:
                    if q in ("temp", "rh", "pres", "wspd"):
                        value = r2(math.fsum(d[q]) / n)
                    elif q == "wdir":
                        s = wvec.get(h)
                        if s and math.hypot(s[0], s[1]) > 1e-9:
                            ang = math.degrees(math.atan2(s[0], s[1])) % 360.0
                            ang = round(ang, 2)
                            value = 0.0 if ang >= 360 else ang
                    else:
                        value = r2(rain_inc.get(h, 0.0))
                entry[q] = {"value": value, "n": n}
            hours.append(entry)
            h += 3600
        out["stations"].append({"station": sid, "interval_s": int(interval), "hours": hours})

    with open(outfile, "w", encoding="utf-8") as fh:
        json.dump(out, fh)


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
"}
